fn frame(t: i32) {
    let h: i32 = host::display::height();
    if t % 30 == 0 {
        host::audio::tone(880, 40, 3);
    }
    let mut vol: i32 = host::display::state_get(0);
    if host::display::state_get(1) == 0 {
        host::display::state_set(1, 1);
        vol = 80;
    }
    if host::display::pointer_down() == 1 {
        vol = (h - host::display::pointer_y()) * 100 / h;
        if vol < 0 { vol = 0; }
        if vol > 100 { vol = 100; }
        host::audio::set_volume(vol);
    }
    host::display::state_set(0, vol);
    let mut bg: i32 = 0x101010;
    if t % 30 < 4 { bg = 0x203040; }
    host::display::clear(bg);
    host::display::draw_string(8, 10, "METRONOME", 0xffffff, 2);
    host::display::draw_string(8, 40, "VOL", 0x808080, 1);
    host::display::draw_number(40, 40, vol, 0x00ff00, 1);
    host::display::present();
}
